<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import Icon from '../components/Icon.vue'
import AnalysisNotice from '../components/AnalysisNotice.vue'
import {state,t,fmt,api,wp,notify,writeAccess,activeJob} from '../state'
const period=ref('day'),selectedId=ref(''),busy=ref(false)
const periods=computed(()=>[{id:'day',label:t('Daily','За день'),subtitle:t('The next 24 hours','Ближайшие решения'),icon:'Sunrise',hint:t('Urgent choices and what to check today.','Срочные решения и проверки на сегодня.')},{id:'week',label:t('Weekly','За неделю'),subtitle:t('Patterns in perspective','Изменения и закономерности'),icon:'CalendarDays',hint:t('Connect developments and identify the week’s patterns.','Связи между событиями и тенденции недели.')},{id:'month',label:t('Monthly','За месяц'),subtitle:t('The strategic view','Стратегический взгляд'),icon:'Telescope',hint:t('Scenarios, priorities and the agenda for next month.','Сценарии, приоритеты и повестка следующего месяца.')}])
const history=computed(()=>state.briefs.filter(b=>b.period===period.value))
const selected=computed(()=>history.value.find(b=>b.id===selectedId.value)||history.value[0])
const c=computed(()=>selected.value?.[state.locale]||selected.value?.en)
const newEvidence=computed(()=>{if(!selected.value)return 0;const start=Date.now()-({day:1,week:7,month:30}[period.value]||1)*86400000;return state.events.filter(e=>new Date(e.published_at||e.created_at).getTime()>=start&&!selected.value.event_ids.includes(e.id)).length})
watch(()=>state.briefs.length,()=>{busy.value=false})
watch(()=>activeJob.value?.id,id=>{if(!id)busy.value=false})
async function generate(){busy.value=true;try{const job=await api(wp('/briefs'),{method:'POST',body:{period:period.value}});state.jobs=[job,...state.jobs.filter(j=>j.id!==job.id)];notify(t('Your brief is being prepared from verified events.','Сводка готовится на основе проверенных событий.'))}catch(e:any){notify(e.message,true);busy.value=false}}
function open(id:string){state.selectedEvent=state.events.find(e=>e.id===id)}
function printBrief(){window.print()}
async function copy(){if(!c.value)return;const text=[c.value.title,c.value.executive_summary,...c.value.themes.map((x:any)=>x.title+'\n'+x.analysis),...c.value.priorities.map((x:any)=>x.action),t('Watch next','Что отслеживать'),...c.value.watch_next,t('AI-generated decision support. Model interpretations are not the bank’s official position. Not an individual investment recommendation.','Аналитика подготовлена с помощью ИИ. Выводы модели не являются официальной позицией банка. Не является индивидуальной инвестиционной рекомендацией.')].join('\n\n');try{await navigator.clipboard.writeText(text);notify(t('Brief copied to clipboard.','Сводка скопирована.'))}catch{notify(t('Copy is unavailable in this browser. Use Print / PDF.','Копирование недоступно. Используйте печать / PDF.'),true)}}
</script>
<template><div class="page-heading"><div><span class="eyebrow">{{t('MAKE ROOM FOR THE BIG PICTURE','ВРЕМЯ ДЛЯ ОБЩЕЙ КАРТИНЫ')}}</span><h1>{{t('Your executive briefing.','Ваша бизнес-сводка.')}}</h1><p>{{t('A clear narrative, grounded in the events that matter to your business.','Связная картина на основе событий, значимых для вашего бизнеса.')}}</p></div><button v-if="writeAccess" class="btn primary" @click="generate" :disabled="!!activeJob"><Icon :name="activeJob?'LoaderCircle':'Sparkles'" :class="{spin:!!activeJob}" :size="17"/>{{t('Generate brief','Подготовить сводку')}}</button></div>
<div class="brief-periods"><button v-for="p in periods" :key="p.id" class="card period-card" :class="{active:period===p.id}" @click="period=p.id;selectedId='' "><span class="stat-icon purple"><Icon :name="p.icon" :size="21"/></span><div><strong>{{p.label}}</strong><span>{{p.subtitle}}</span></div><Icon :name="period===p.id?'CircleCheck':'Circle'" :size="19"/><p>{{p.hint}}</p></button></div>
<div v-if="newEvidence" class="notice" role="status"><Icon name="RefreshCw" :size="18"/><span>{{newEvidence}} {{t('new signals are available since this edition. Prepare an updated brief to include them.','новых сигналов появились после подготовки выпуска. Создайте обновлённую сводку, чтобы учесть их.')}}</span></div><div v-if="selected" class="brief-layout"><article class="brief-paper" id="brief-print"><div class="brief-masthead"><span class="brand"><Icon name="AudioLines" :size="24"/>SignalDesk</span><span>{{t('EXECUTIVE INTELLIGENCE','БИЗНЕС-АНАЛИТИКА')}}</span></div><div class="row between wrap"><span class="eyebrow">{{periods.find(p=>p.id===period)?.label}} · {{state.workspace.name}}</span><span class="small muted">{{fmt(selected.start)}} — {{fmt(selected.end,{month:'short',day:'numeric',year:'numeric'})}}</span></div><h1>{{c.title}}</h1><div class="brief-byline"><span class="live-dot"></span>{{t('Prepared for','Подготовлено для')}} {{state.workspace.decision_role.toUpperCase()}} · {{selected.event_count}} {{t('verified events','событий')}}<span v-if="selected.is_demo"> · {{t('Synthetic scenarios','Учебные сценарии')}}</span></div><p class="brief-lead">{{c.executive_summary}}</p><div class="brief-key-stats"><div><strong>{{selected.event_count}}</strong><span>{{t('Events in view','Событий в обзоре')}}</span></div><div><strong>{{selected.risk_count}}</strong><span>{{t('Risk signals','Рисков')}}</span></div><div><strong>{{selected.opportunity_count}}</strong><span>{{t('Opportunities','Возможностей')}}</span></div></div><section class="brief-section"><span class="eyebrow">01 / {{t('THE DEVELOPMENTS THAT CONNECT','СВЯЗИ МЕЖДУ СОБЫТИЯМИ')}}</span><div v-for="(theme,i) in c.themes" :key="i" class="brief-theme"><h2>{{theme.title}}</h2><p>{{theme.analysis}}</p><div class="brief-citations"><button v-for="(id,j) in theme.event_ids" :key="id" @click="open(id)"><Icon name="Link2" :size="12"/>{{t('Source event','Событие')}} {{Number(j)+1}}<Icon name="ArrowUpRight" :size="12"/></button></div></div></section><section class="brief-section"><span class="eyebrow">02 / {{t('YOUR DECISION AGENDA','ПОВЕСТКА РЕШЕНИЙ')}}</span><div v-for="(a,i) in c.priorities" :key="i" class="brief-priority"><span>{{Number(i)+1}}</span><div><strong>{{a.action}}</strong><p>{{a.timeframe}}</p><div class="brief-citations"><button v-for="id in a.event_ids" :key="id" @click="open(id)">{{t('See supporting event','Посмотреть событие')}}<Icon name="ArrowUpRight" :size="12"/></button></div></div></div></section><section class="brief-section"><span class="eyebrow">03 / {{t('WHAT TO WATCH NEXT','ЧТО ОТСЛЕЖИВАТЬ ДАЛЬШЕ')}}</span><p v-for="w in c.watch_next" :key="w" class="watch-item"><Icon name="Focus" :size="17"/>{{w}}</p></section><div class="brief-gaps"><Icon name="Info" :size="17"/><div><strong>{{t('The limits of this picture','Границы этой картины')}}</strong><p v-for="g in c.gaps" :key="g">{{g}}</p><p>{{t('This brief uses only the events collected in the stated period. It is not a complete market assessment.','Сводка использует только собранные события указанного периода и не является полным обзором рынка.')}}</p></div></div><AnalysisNotice/><footer class="brief-paper-footer"><span>SignalDesk · {{t('Your business, in context','Ваш бизнес в контексте')}}</span><span>{{fmt(selected.generated_at,{dateStyle:'medium',timeStyle:'short'})}}</span></footer></article><aside class="brief-sidebar"><section class="card"><h3>{{t('Take the insight with you','Сохраните полезные выводы')}}</h3><p class="small muted">{{t('A briefing ready for your next leadership discussion.','Сводка для следующего обсуждения с командой.')}}</p><button class="btn secondary full" @click="printBrief"><Icon name="Printer" :size="16"/>{{t('Print / save PDF','Печать / сохранить PDF')}}</button><button class="btn ghost full mt-sm" @click="copy"><Icon name="Copy" :size="16"/>{{t('Copy brief','Скопировать сводку')}}</button></section><section class="card"><h3>{{t('Previous editions','Предыдущие выпуски')}}</h3><button v-for="b in history" :key="b.id" class="brief-history" :class="{active:selected.id===b.id}" @click="selectedId=b.id"><Icon name="FileText" :size="17"/><span>{{fmt(b.generated_at,{dateStyle:'medium',timeStyle:'short'})}}<small>{{b.event_count}} {{t('events','событий')}}</small></span></button></section><div class="notice"><Icon name="Mail" :size="18"/><p>{{t('Enable brief delivery in your account preferences. Daily editions run at 10:00 Moscow time; weekly on Monday and monthly on the first day.','Включите доставку сводок в профиле. Дневные выпуски — в 10:00 МСК, недельные — по понедельникам, месячные — первого числа.')}}</p></div></aside></div>
<div v-else class="card empty brief-empty"><span class="empty-icon"><Icon name="FileChartColumn" :size="34"/></span><span class="eyebrow">{{t('A NEW PERSPECTIVE IS ONE STEP AWAY','НОВЫЙ ВЗГЛЯД В ОДНОМ ШАГЕ')}}</span><h2>{{t('Bring the signals together.','Соберите сигналы в общую картину.')}}</h2><p>{{periods.find(p=>p.id===period)?.hint}} {{t('We’ll use verified events in the selected period to prepare a concise, company-specific briefing.','На основе проверенных событий периода мы подготовим краткую сводку для вашей компании.')}}</p><button v-if="writeAccess" class="btn primary large-btn" :disabled="!!activeJob" @click="generate"><Icon name="Sparkles" :size="17"/>{{t('Prepare my','Подготовить')}} {{periods.find(p=>p.id===period)?.label.toLowerCase()}} {{t('brief','сводку')}}</button><span class="small muted">{{t('No events in this period? Start with a monitoring run.','Нет событий за период? Сначала запустите мониторинг.')}}</span></div>
</template>
